// Overview: "events over time" chart (uPlot, vendored). Data comes from the JSON API;
// series names are table names generated by ThreatLens, rendered as text by uPlot.
(function () {
  "use strict";

  var PALETTE = ["#38bdf8", "#f59e0b", "#a78bfa", "#34d399", "#f472b6", "#f87171", "#94a3b8"];

  function css(name, fallback) {
    var v = getComputedStyle(document.documentElement).getPropertyValue(name);
    return v ? v.trim() : fallback;
  }

  function draw(el, data) {
    var names = Object.keys(data.series);
    if (!data.buckets.length || !names.length) return;
    el.textContent = "";
    var xs = data.buckets.map(function (ms) { return ms / 1000; });
    var rows = [xs];
    var series = [{}];
    names.forEach(function (name, i) {
      rows.push(data.series[name]);
      var color = PALETTE[i % PALETTE.length];
      series.push({
        label: name,
        stroke: color,
        fill: color + "22",
        width: 1.5,
        points: { show: false },
      });
    });
    var axis = {
      stroke: css("--text-muted", "#93a1b0"),
      grid: { stroke: css("--border", "#243040"), width: 1 },
      ticks: { stroke: css("--border", "#243040"), width: 1 },
    };
    var opts = {
      width: el.clientWidth,
      height: 260,
      series: series,
      axes: [axis, Object.assign({}, axis, { size: 56 })],
      scales: { x: { time: true } },
      legend: { live: true },
      tzDate: function (ts) { return uPlot.tzDate(new Date(ts * 1e3), "Etc/UTC"); },
    };
    var plot = new uPlot(opts, rows, el);
    var resize = function () { plot.setSize({ width: el.clientWidth, height: 260 }); };
    window.addEventListener("resize", resize);
  }

  function init() {
    var el = document.getElementById("events-chart");
    if (!el || typeof uPlot === "undefined") return;
    fetch(el.getAttribute("data-src"), { credentials: "same-origin" })
      .then(function (r) { return r.ok ? r.json() : null; })
      .then(function (data) { if (data) draw(el, data); })
      .catch(function () { /* chart is optional */ });
  }

  if (document.readyState === "loading") {
    document.addEventListener("DOMContentLoaded", init);
  } else {
    init();
  }
})();
